#![forbid(unsafe_code)]

//! ARM (AArch64) backend using the shared ISA framework.
//!
//! Mode, feature, and backend types are generated by `define_arch!`.
//! The `ArchitectureBackend` trait impl is also generated by the macro
//! via `backend_impl { ... }`, delegating to standalone functions below.

use robustone_core::ir::{ArchitectureId, Operand, RegisterId};
use robustone_core::types::error::{DecodeErrorKind, DisasmError};
use robustone_isa::{DecodeProfile, FeatureSet, FormatSpec, InstructionRead, InstructionSpec};

// ---------------------------------------------------------------------------
// Field enum
// ---------------------------------------------------------------------------

/// AArch64 instruction fields used by format specs and field extractors.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ArmField {
    // General-purpose registers
    Rd,
    Rn,
    Rm,
    Ra,
    Rt,
    Rt2,
    Rs,
    // Immediates
    Imm9,
    Imm12,
    Imm16,
    Imm19,
    Imm26,
    Immhi,
    Immlo,
    Imm7,
    Cond,
    Shift,
    Imm6,
    Hw,
    N,
    Immr,
    Imms,
    // FP / SIMD
    Ftype,
    Opcode,
    Size,
    Q,
    U,
    L,
    M,
    H,
}

// ---------------------------------------------------------------------------
// Registers
// ---------------------------------------------------------------------------

robustone_isa_macros::define_registers! {
    arch = Arm;
    bank Gpr {
        count = 31;
        base_id = 0;
        canonical = "x{n}";
    }
    bank Vec {
        count = 32;
        base_id = 64;
        canonical = "v{n}";
    }
}

// ---------------------------------------------------------------------------
// Architecture definition
// ---------------------------------------------------------------------------

robustone_isa_macros::define_arch! {
    pub arch Arm {
        word = u32;
        endian = little;
        instruction_length = fixed(4);
        modes { AArch64 = "aarch64"; };
        features: u8 { BASE = 0; FP = 1; SIMD = 2; CRYPTO = 3; };
        registers = arm_registers;
        formats = arm_formats;
        specs = arm_specs;
        render = ArmRenderPolicy;
        backend_impl {
            field = ArmField;
            register_class = ArmRegisterClass;
            architecture_id = ArchitectureId::Arm;
            read_instruction = arm_read_instruction;
            lookup = arm_lookup;
            lower_register = arm_lower_register;
            extract_field = arm_extract_field;
            apply_aliases = arm_apply_aliases;
        }
    }
}

// ---------------------------------------------------------------------------
// Spec modules
// ---------------------------------------------------------------------------

/// Base integer data-processing instruction specs (arithmetic, logical, bitfield, etc.).
pub mod specs_base {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_base.rs");
}
/// Branch instruction specs (B, BL, B.cond, CBZ, CBNZ, TBZ, TBNZ).
pub mod specs_branch {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_branch.rs");
}
/// Load/store instruction specs (immediate, literal, pair, atomic).
pub mod specs_loadstore {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_loadstore.rs");
}
/// Load/store register offset instruction specs.
/// Kept in a separate slice because their masks overlap with unsigned-immediate
/// specs; priority-based resolution in `arm_lookup` handles selection at runtime.
pub mod specs_loadstore_regoffset {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_loadstore_regoffset.rs");
}
/// Scalar floating-point data-processing specs (1-source, 2-source, 3-source, comparison, conversion).
pub mod specs_scalar_fp {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_scalar_fp.rs");
}
/// System instruction specs (NOP, SVC, BRK, barriers, MSR/MRS).
pub mod specs_system {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_system.rs");
}
/// Advanced SIMD vector instruction specs (three same, two-reg misc, across lanes, copy/extract, indexed element, modified immediate, shift immediate, table lookup, crypto).
pub mod specs_vector {
    use super::*;
    use robustone_isa::ModeSet;
    include!("specs_vector.rs");
}

/// Concatenated slices of all AArch64 instruction specs for validation and lookup.
pub static ALL_SPEC_SLICES: &[&[InstructionSpec<ArmBackend>]] = &[
    specs_base::SPECS,
    specs_branch::SPECS,
    specs_loadstore::SPECS,
    specs_loadstore_regoffset::SPECS,
    specs_scalar_fp::SPECS,
    specs_system::SPECS,
    specs_vector::SPECS,
];

fn all_arm_specs() -> impl Iterator<Item = &'static InstructionSpec<ArmBackend>> {
    ALL_SPEC_SLICES.iter().flat_map(|s| s.iter())
}

// ---------------------------------------------------------------------------
// Backend functions
// ---------------------------------------------------------------------------

/// Read a single 32-bit little-endian AArch64 instruction from bytes.
fn arm_read_instruction(bytes: &[u8]) -> Result<InstructionRead<u32>, DisasmError> {
    if bytes.len() < 4 {
        return Err(DisasmError::decode_failure(
            DecodeErrorKind::NeedMoreBytes,
            Some("arm".to_string()),
            "need 4 bytes",
        ));
    }
    let word = u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]);
    Ok(InstructionRead {
        raw: word,
        length: 4,
    })
}

/// Look up the instruction spec matching `word` within the enabled feature set.
/// Uses hierarchical op0 pre-filtering to reduce linear search cost.
fn arm_lookup(
    word: u32,
    profile: &DecodeProfile<ArmBackend>,
) -> Option<&'static InstructionSpec<ArmBackend>> {
    let op0 = ((word >> 25) & 0xF) as u8;

    // Hierarchical dispatch: pre-filter by op0 range before linear match.
    // Higher-priority (more specific) specs are tried first.
    all_arm_specs()
        .filter(|spec| {
            let spec_op0 = ((spec.pattern().value >> 25) & 0xF) as u8;
            let spec_mask = ((spec.pattern().mask >> 25) & 0xF) as u8;
            let op0_matches = (op0 & spec_mask) == spec_op0;

            op0_matches
                && (word & spec.pattern().mask) == spec.pattern().value
                && profile.features.contains(spec.features())
        })
        .max_by_key(|spec| spec.priority())
}

/// Lower a raw register number into a `RegisterId` for the given register class.
fn arm_lower_register(
    class: ArmRegisterClass,
    raw: u32,
    _profile: &DecodeProfile<ArmBackend>,
) -> RegisterId {
    match lower_register(class, raw) {
        Ok(id) => RegisterId::arm(id),
        Err(_) => RegisterId::arm(raw),
    }
}

/// Extract the value of `field` from `word` according to the format definition.
fn arm_extract_field(
    word: u32,
    format: &FormatSpec<ArmField>,
    field: ArmField,
) -> Result<u32, DisasmError> {
    // Search format fields for matching field type and extract bits
    for f in format.fields() {
        if f.field_type() == field {
            let mask = ((1u64 << f.length()) - 1) as u32;
            return Ok((word >> f.start()) & mask);
        }
    }
    Err(DisasmError::decode_failure(
        DecodeErrorKind::InvalidField,
        Some("arm".to_string()),
        format!("field {:?} not found in format {}", field, format.name()),
    ))
}

// ---------------------------------------------------------------------------
// Alias / operand rewrite
// ---------------------------------------------------------------------------

/// Rewrite decoded operands and mnemonics to match AArch64 assembly conventions.
///
/// Handles SIMD arrangement suffixes, scalar FP register names, indexed element
/// notation, shift immediates, modified immediates, and various instruction aliases.
fn arm_apply_aliases(decoded: &mut robustone_core::ir::DecodedInstruction) {
    if decoded.raw_bytes.len() < 4 {
        return;
    }
    let word = u32::from_le_bytes([
        decoded.raw_bytes[0],
        decoded.raw_bytes[1],
        decoded.raw_bytes[2],
        decoded.raw_bytes[3],
    ]);

    let opcode_id = decoded.opcode_id.clone().unwrap_or_default();

    // Load/store: combine base register and offset into memory operand text.
    if is_loadstore_opcode(&opcode_id) {
        apply_loadstore_aliases(decoded, word, &opcode_id);
        return;
    }

    if opcode_id.starts_with("VEC_") {
        // Special-case SHA three-register: mixed scalar/vector operands.
        if is_sha_three_reg_opcode(&opcode_id) {
            for (i, op) in decoded.operands.iter_mut().enumerate() {
                if let Operand::Register { register } = op
                    && register.architecture == ArchitectureId::Arm
                    && (64..96).contains(&register.id)
                {
                    let reg_num = register.id - 64;
                    match (opcode_id.as_str(), i) {
                        ("VEC_SHA1C" | "VEC_SHA1P" | "VEC_SHA1M", 1) => {
                            *op = Operand::Text {
                                value: format!("s{}", reg_num),
                            };
                        }
                        ("VEC_SHA1C" | "VEC_SHA1P" | "VEC_SHA1M", 0)
                        | ("VEC_SHA256H" | "VEC_SHA256H2", 0)
                        | ("VEC_SHA256H" | "VEC_SHA256H2", 1) => {
                            *op = Operand::Text {
                                value: format!("q{}", reg_num),
                            };
                        }
                        _ => {
                            *op = Operand::Text {
                                value: format!("v{}.4s", reg_num),
                            };
                        }
                    }
                }
            }
            return;
        }

        // Table lookup: render register list for Rn and .16b for Rd/Rm.
        if is_table_lookup_opcode(&opcode_id) {
            let len = ((word >> 13) & 0x3) as usize;
            for (i, op) in decoded.operands.iter_mut().enumerate() {
                if let Operand::Register { register } = op
                    && register.architecture == ArchitectureId::Arm
                    && (64..96).contains(&register.id)
                {
                    let reg_num = register.id - 64;
                    match i {
                        0 | 2 => {
                            *op = Operand::Text {
                                value: format!("v{}.16b", reg_num),
                            };
                        }
                        1 => {
                            let mut list = String::new();
                            list.push('{');
                            for j in 0..=len {
                                if j > 0 {
                                    list.push_str(", ");
                                }
                                list.push_str(&format!("v{}.16b", reg_num + j as u32));
                            }
                            list.push('}');
                            *op = Operand::Text { value: list };
                        }
                        _ => {}
                    }
                }
            }
            return;
        }

        // Copy/Extract SIMD instructions: DUP, INS, EXT, SMOV, UMOV.
        if is_copy_extract_opcode(&opcode_id) {
            let q = ((word >> 30) & 0x1) as u8;
            let imm5 = ((word >> 16) & 0x1F) as u8;
            let size = simd_element_size_from_imm5(imm5);
            let arr = vec_arrangement_suffix(size, q);
            let elem = element_type_suffix(size);
            let elem_index = imm5 >> (size + 1);

            match opcode_id.as_str() {
                "VEC_DUP_ELEMENT" => {
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::Arm
                            && (64..96).contains(&register.id)
                        {
                            let reg_num = register.id - 64;
                            *op = match i {
                                0 => Operand::Text {
                                    value: format!("v{}{}", reg_num, arr),
                                },
                                1 => Operand::Text {
                                    value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                },
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_DUP_GENERAL" => {
                    let is_64bit = size == 3;
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::Arm
                        {
                            *op = match i {
                                0 if (64..96).contains(&register.id) => {
                                    let reg_num = register.id - 64;
                                    Operand::Text {
                                        value: format!("v{}{}", reg_num, arr),
                                    }
                                }
                                1 => {
                                    let reg_num = register.id;
                                    Operand::Text {
                                        value: if is_64bit {
                                            format!("x{}", reg_num)
                                        } else {
                                            format!("w{}", reg_num)
                                        },
                                    }
                                }
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_INS_GENERAL" => {
                    let is_64bit = size == 3;
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::Arm
                        {
                            *op = match i {
                                0 if (64..96).contains(&register.id) => {
                                    let reg_num = register.id - 64;
                                    Operand::Text {
                                        value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                    }
                                }
                                1 => {
                                    let reg_num = register.id;
                                    Operand::Text {
                                        value: if is_64bit {
                                            format!("x{}", reg_num)
                                        } else {
                                            format!("w{}", reg_num)
                                        },
                                    }
                                }
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_INS_ELEMENT" => {
                    let bits14_11 = ((word >> 11) & 0xF) as u8;
                    let src_index = bits14_11 >> size;
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::Arm
                            && (64..96).contains(&register.id)
                        {
                            let reg_num = register.id - 64;
                            *op = match i {
                                0 => Operand::Text {
                                    value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                },
                                1 => Operand::Text {
                                    value: format!("v{}.{}[{}]", reg_num, elem, src_index),
                                },
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_SMOV" => {
                    let is_64bit = q == 1;
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::Arm
                        {
                            *op = match i {
                                0 => {
                                    let reg_num = register.id;
                                    Operand::Text {
                                        value: if is_64bit {
                                            format!("x{}", reg_num)
                                        } else {
                                            format!("w{}", reg_num)
                                        },
                                    }
                                }
                                1 if (64..96).contains(&register.id) => {
                                    let reg_num = register.id - 64;
                                    Operand::Text {
                                        value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                    }
                                }
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_UMOV" => {
                    let is_64bit = q == 1 && size == 3;
                    let is_mov_alias = (q == 0 && size == 2) || (q == 1 && size == 3);
                    if is_mov_alias {
                        decoded.mnemonic = "mov".to_string();
                    }
                    for (i, op) in decoded.operands.iter_mut().enumerate() {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::Arm
                        {
                            *op = match i {
                                0 => {
                                    let reg_num = register.id;
                                    Operand::Text {
                                        value: if is_64bit {
                                            format!("x{}", reg_num)
                                        } else {
                                            format!("w{}", reg_num)
                                        },
                                    }
                                }
                                1 if (64..96).contains(&register.id) => {
                                    let reg_num = register.id - 64;
                                    Operand::Text {
                                        value: format!("v{}.{}[{}]", reg_num, elem, elem_index),
                                    }
                                }
                                _ => continue,
                            };
                        }
                    }
                }
                "VEC_EXT" => {
                    let ext_arr = if q == 1 { ".16b" } else { ".8b" };
                    let imm4 = ((word >> 11) & 0xF) as u8;
                    for op in &mut decoded.operands {
                        if let Operand::Register { register } = op
                            && register.architecture == ArchitectureId::Arm
                            && (64..96).contains(&register.id)
                        {
                            let reg_num = register.id - 64;
                            *op = Operand::Text {
                                value: format!("v{}{}", reg_num, ext_arr),
                            };
                        }
                    }
                    decoded.operands.push(Operand::Immediate {
                        value: imm4 as i64,
                        unsigned_mask: 0xF,
                    });
                }
                _ => {}
            }
            return;
        }

        // Indexed Element SIMD instructions.
        // FMLAL2 indexed element: special handling because encoding uses size=2
        // but operates on H (16-bit) elements.
        if opcode_id == "VEC_FMLAL2_INDEXED" {
            let q = ((word >> 30) & 0x1) as u8;
            let h = ((word >> 11) & 0x1) as u8;
            let l = ((word >> 21) & 0x1) as u8;
            let bit20 = ((word >> 20) & 0x1) as u8;
            let index = ((h as u32) << 2) | ((l as u32) << 1) | (bit20 as u32);
            let rd_suffix = if q == 0 { ".2s" } else { ".4s" };
            let rn_suffix = if q == 0 { ".2s" } else { ".4s" };

            for (i, op) in decoded.operands.iter_mut().enumerate() {
                if let Operand::Register { register } = op
                    && register.architecture == ArchitectureId::Arm
                    && (64..96).contains(&register.id)
                {
                    let reg_num = register.id - 64;
                    let adjusted_reg = if i == 2 { reg_num & 0xF } else { reg_num };
                    *op = match i {
                        0 => Operand::Text {
                            value: format!("v{}{}", adjusted_reg, rd_suffix),
                        },
                        1 => Operand::Text {
                            value: format!("v{}{}", adjusted_reg, rn_suffix),
                        },
                        2 => Operand::Text {
                            value: format!("v{}.h[{}]", adjusted_reg, index),
                        },
                        _ => continue,
                    };
                }
            }
            return;
        }

        if is_indexed_element_opcode(&opcode_id) {
            let size = ((word >> 22) & 0x3) as u8;
            let q = ((word >> 30) & 0x1) as u8;
            let h = ((word >> 11) & 0x1) as u8;
            let l = ((word >> 21) & 0x1) as u8;
            let bit20 = ((word >> 20) & 0x1) as u8;

            // Compute element index based on size and Q.
            let index = match (size, q) {
                (0, 0) | (1, 0) => (l << 1) | h,                // FP16/H Q=0: {L, H}
                (0, 1) | (1, 1) => (h << 2) | (l << 1) | bit20, // FP16/H Q=1: {H, L, M}
                (2, _) => (h << 1) | l,                         // S: {H, L}
                (3, _) => h,                                    // D: {H}
                _ => 0,
            };

            // Compute arrangement suffix for Rd and Rn.
            let is_fp = is_fp_indexed_opcode(&opcode_id);
            let rn_suffix = if is_fp {
                fp_indexed_arrangement_suffix(size, q)
            } else {
                vec_arrangement_suffix(size, q)
            };

            // For long operations, destination is wider.
            let is_long = is_long_indexed_opcode(&opcode_id);
            let rd_suffix = if is_long {
                match size {
                    1 => ".4s", // H -> S
                    2 => ".2d", // S -> D
                    _ => rn_suffix,
                }
            } else {
                rn_suffix
            };

            // Widening instructions use a "2" suffix when Q=1.
            if is_long && q == 1 {
                decoded.mnemonic.push('2');
            }

            // Element type suffix for indexed register.
            let elem = match size {
                0 => "h", // FP16 uses h element
                1 => "h",
                2 => "s",
                3 => "d",
                _ => "",
            };

            // For H/FP16 elements (size < 2), Rm uses only 4 bits (bits 19:16)
            // and bit 20 (M) is part of the element index. For S/D elements
            // (size >= 2), Rm uses 5 bits {M, Rm[3:0]}.
            let rm_4bit_only = size < 2;

            for (i, op) in decoded.operands.iter_mut().enumerate() {
                if let Operand::Register { register } = op
                    && register.architecture == ArchitectureId::Arm
                    && (64..96).contains(&register.id)
                {
                    let reg_num = register.id - 64;
                    // Mask Rm to 4 bits only for H/FP16 element sizes.
                    let adjusted_reg = if i == 2 && rm_4bit_only {
                        reg_num & 0xF
                    } else {
                        reg_num
                    };
                    *op = match i {
                        0 => Operand::Text {
                            value: format!("v{}{}", adjusted_reg, rd_suffix),
                        },
                        1 => Operand::Text {
                            value: format!("v{}{}", adjusted_reg, rn_suffix),
                        },
                        2 => Operand::Text {
                            value: format!("v{}.{}[{}]", adjusted_reg, elem, index),
                        },
                        _ => continue,
                    };
                }
            }
            return;
        }

        // Advanced SIMD Modified Immediate.
        if is_modified_imm_opcode(&opcode_id) {
            let op = ((word >> 29) & 0x1) as u8;
            let q = ((word >> 30) & 0x1) as u8;
            let cmode = ((word >> 12) & 0xF) as u8;
            let a = ((word >> 18) & 0x1) as u8;
            let b = ((word >> 17) & 0x1) as u8;
            let c = ((word >> 16) & 0x1) as u8;
            let d = ((word >> 9) & 0x1) as u8;
            let e = ((word >> 8) & 0x1) as u8;
            let f = ((word >> 7) & 0x1) as u8;
            let g = ((word >> 6) & 0x1) as u8;
            let h = ((word >> 5) & 0x1) as u8;
            let imm8 =
                (a << 7) | (b << 6) | (c << 5) | (d << 4) | (e << 3) | (f << 2) | (g << 1) | h;
            let rd = (word & 0x1F) as u8;

            // Determine mnemonic and arrangement.
            let (mnemonic, arr_suffix, is_scalar) = match (op, cmode) {
                // movi: op=0, cmode even (including 14)
                (0, c) if c < 15 && c % 2 == 0 => {
                    ("movi", modified_imm_arrangement(cmode, q, op), false)
                }
                // orr: op=0, cmode odd
                (0, c) if c < 15 && c % 2 == 1 => {
                    ("orr", modified_imm_arrangement(cmode, q, op), false)
                }
                // fmov: op=0, cmode=15
                (0, 15) => ("fmov", modified_imm_fp_arrangement(q, op), false),
                // mvni: op=1, cmode even < 14
                (1, c) if c < 14 && c % 2 == 0 => {
                    ("mvni", modified_imm_arrangement(cmode, q, op), false)
                }
                // bic: op=1, cmode odd < 14
                (1, c) if c < 14 && c % 2 == 1 => {
                    ("bic", modified_imm_arrangement(cmode, q, op), false)
                }
                // movi 64-bit: op=1, cmode=14
                (1, 14) => ("movi", modified_imm_arrangement(cmode, q, op), q == 0),
                // fmov D: op=1, cmode=15
                (1, 15) => ("fmov", modified_imm_fp_arrangement(q, op), false),
                _ => ("movi", "", false),
            };

            decoded.mnemonic = mnemonic.to_string();

            // Format immediate operand.
            let imm_text = if cmode == 14 && op == 1 {
                // 64-bit immediate: each bit of imm8 expands to a byte.
                let imm64 = ((a as u64) * 0xFF00000000000000)
                    | ((b as u64) * 0x00FF000000000000)
                    | ((c as u64) * 0x0000FF0000000000)
                    | ((d as u64) * 0x000000FF00000000)
                    | ((e as u64) * 0x00000000FF000000)
                    | ((f as u64) * 0x0000000000FF0000)
                    | ((g as u64) * 0x000000000000FF00)
                    | ((h as u64) * 0x00000000000000FF);
                format!("#0x{:016x}", imm64)
            } else if cmode == 15 {
                // FP immediate.
                let fp_val = fp_expand_imm(imm8, op, q);
                format!("#{:.8}", fp_val)
            } else {
                // Integer immediate with optional shift.
                let shift = modified_imm_shift(cmode);
                if shift == 0 {
                    format!("#{}", imm8)
                } else {
                    let shift_type = if cmode >= 12 { "msl" } else { "lsl" };
                    format!("#{}, {} #{}", imm8, shift_type, shift)
                }
            };

            // Build operand text.
            let reg_text = if is_scalar {
                format!("d{}", rd)
            } else {
                format!("v{}{}", rd, arr_suffix)
            };

            decoded.operands = vec![
                Operand::Text { value: reg_text },
                Operand::Text { value: imm_text },
            ];
            return;
        }

        // Advanced SIMD Vector Shift Immediate.
        if is_shift_imm_opcode(&opcode_id) {
            let u = ((word >> 29) & 0x1) as u8;
            let q = ((word >> 30) & 0x1) as u8;
            let opcode = ((word >> 11) & 0x1F) as u8;
            let immh = ((word >> 19) & 0xF) as u8;
            let immb = ((word >> 16) & 0x7) as u8;
            let immh_immb = (immh << 3) | immb;
            let rd = (word & 0x1F) as u8;
            let rn = ((word >> 5) & 0x1F) as u8;

            let esize = shift_imm_esize(immh);
            if esize == 0 {
                return;
            }

            // Determine if this is a right shift, left shift, narrowing, or widening.
            let (mnemonic, src_esize, dest_esize, is_narrowing, is_widening) = match (opcode, u) {
                // Basic right shifts
                (0b00000, 0) => ("sshr", esize, esize, false, false),
                (0b00000, 1) => ("ushr", esize, esize, false, false),
                (0b00010, 0) => ("ssra", esize, esize, false, false),
                (0b00010, 1) => ("usra", esize, esize, false, false),
                (0b00100, 0) => ("srshr", esize, esize, false, false),
                (0b00100, 1) => ("urshr", esize, esize, false, false),
                (0b00110, 0) => ("srsra", esize, esize, false, false),
                (0b00110, 1) => ("ursra", esize, esize, false, false),
                (0b01000, 1) => ("sri", esize, esize, false, false),
                // Left shifts
                (0b01010, 0) => ("shl", esize, esize, false, false),
                (0b01010, 1) => ("sli", esize, esize, false, false),
                (0b01100, 1) => ("sqshlu", esize, esize, false, false),
                (0b01110, 0) => ("sqshl", esize, esize, false, false),
                (0b01110, 1) => ("uqshl", esize, esize, false, false),
                // Narrowing right shifts
                (0b10000, 0) => ("shrn", esize * 2, esize, true, false),
                (0b10000, 1) => ("sqshrun", esize * 2, esize, true, false),
                (0b10001, 0) => ("rshrn", esize * 2, esize, true, false),
                (0b10001, 1) => ("sqrshrun", esize * 2, esize, true, false),
                (0b10010, 0) => ("sqshrn", esize * 2, esize, true, false),
                (0b10010, 1) => ("uqshrn", esize * 2, esize, true, false),
                (0b10011, 0) => ("sqrshrn", esize * 2, esize, true, false),
                (0b10011, 1) => ("uqrshrn", esize * 2, esize, true, false),
                // Widening left shifts
                (0b10100, 0) => ("sshll", esize, esize * 2, false, true),
                (0b10100, 1) => ("ushll", esize, esize * 2, false, true),
                _ => ("", esize, esize, false, false),
            };

            if mnemonic.is_empty() {
                return;
            }

            decoded.mnemonic = if (is_narrowing || is_widening) && q == 1 {
                format!("{}2", mnemonic)
            } else {
                mnemonic.to_string()
            };

            // Compute shift amount.
            let shift = if is_widening {
                // Widening: left shift, amount = immh:immb - esize
                immh_immb - esize
            } else if is_narrowing {
                // Narrowing: right shift, amount = 2 * esize - immh:immb
                (2 * esize) - immh_immb
            } else if matches!(mnemonic, "shl" | "sli" | "sqshl" | "uqshl" | "sqshlu") {
                // Left shifts
                immh_immb - esize
            } else {
                // Right shifts
                (2 * esize) - immh_immb
            };

            // Build arrangement suffixes.
            let (rd_suffix, rn_suffix) = if is_narrowing {
                // Narrowing: source is always 128-bit, dest depends on Q.
                let src_suf = shift_imm_arrangement(src_esize, 1);
                let dest_suf = shift_imm_arrangement(dest_esize, q);
                (dest_suf, src_suf)
            } else if is_widening {
                // Widening: source depends on Q, dest is always 128-bit.
                let src_suf = shift_imm_arrangement(src_esize, q);
                let dest_suf = shift_imm_arrangement(dest_esize, 1);
                (dest_suf, src_suf)
            } else {
                let suf = shift_imm_arrangement(esize, q);
                (suf, suf)
            };

            decoded.operands = vec![
                Operand::Text {
                    value: format!("v{}{}", rd, rd_suffix),
                },
                Operand::Text {
                    value: format!("v{}{}", rn, rn_suffix),
                },
                Operand::Text {
                    value: format!("#{}", shift),
                },
            ];
            return;
        }

        // Vector SIMD: rewrite Vec register operands to include arrangement suffix.
        let size = ((word >> 22) & 0x3) as u8;
        let q = ((word >> 30) & 0x1) as u8;
        let suffix = if is_fp_vector_opcode(&opcode_id) {
            fp_vec_arrangement_suffix(size, q)
        } else {
            vec_arrangement_suffix(size, q)
        };
        for op in &mut decoded.operands {
            if let Operand::Register { register } = op
                && register.architecture == ArchitectureId::Arm
                && (64..96).contains(&register.id)
            {
                let reg_num = register.id - 64;
                *op = Operand::Text {
                    value: format!("v{}{}", reg_num, suffix),
                };
            }
        }
    } else if is_scalar_fp_opcode(&opcode_id) {
        // Scalar FP: rewrite Vec register operands to s/d/h register names.
        let ftype = ((word >> 22) & 0x3) as u8;
        let prefix = match ftype {
            0 => 's',
            1 => 'd',
            3 => 'h',
            _ => return, // reserved ftype — leave untouched
        };
        for op in &mut decoded.operands {
            if let Operand::Register { register } = op
                && register.architecture == ArchitectureId::Arm
                && (64..96).contains(&register.id)
            {
                let reg_num = register.id - 64;
                *op = Operand::Text {
                    value: format!("{}{}", prefix, reg_num),
                };
            }
        }
    } else {
        // General aliases for base integer, branch, and system instructions.
        apply_general_aliases(decoded, word, &opcode_id);
    }
}

/// Apply aliases and formatting for base integer, branch, and system instructions.
fn apply_general_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    use robustone_core::ir::Operand;

    let address = decoded.address;

    // Branch target computation for PC-relative instructions.
    match opcode_id {
        "B" | "BL" => {
            let imm26 = (word & 0x03FFFFFF) as i32;
            let offset = sign_extend(imm26, 26) << 2;
            let target = (address as i64).wrapping_add(offset as i64) as u64;
            decoded.operands.clear();
            decoded.operands.push(Operand::Text {
                value: format_branch_target(target),
            });
        }
        "B_COND" => {
            let imm19 = ((word >> 5) & 0x7FFFF) as i32;
            let offset = sign_extend(imm19, 19) << 2;
            let target = (address as i64).wrapping_add(offset as i64) as u64;
            let cond = word & 0xF;
            let cond_name = condition_name(cond);
            decoded.mnemonic = format!("b.{}", cond_name);
            decoded.operands.clear();
            decoded.operands.push(Operand::Text {
                value: format_branch_target(target),
            });
        }
        "CBZ" | "CBNZ" => {
            let imm19 = ((word >> 5) & 0x7FFFF) as i32;
            let offset = sign_extend(imm19, 19) << 2;
            let target = (address as i64).wrapping_add(offset as i64) as u64;
            let sf = (word >> 31) & 1;
            let reg_size = if sf == 1 { "x" } else { "w" };
            let rt = word & 0x1F;
            let mnemonic = if opcode_id == "CBZ" { "cbz" } else { "cbnz" };
            decoded.mnemonic = mnemonic.to_string();
            decoded.operands.clear();
            decoded.operands.push(Operand::Text {
                value: format!("{}{}", reg_size, rt),
            });
            decoded.operands.push(Operand::Text {
                value: format_branch_target(target),
            });
        }
        "TBZ" | "TBNZ" => {
            let imm14 = ((word >> 5) & 0x3FFF) as i32;
            let offset = sign_extend(imm14, 14) << 2;
            let target = (address as i64).wrapping_add(offset as i64) as u64;
            let bit_pos = (word >> 19) & 0x1F;
            let reg_size = if bit_pos >= 32 { "x" } else { "w" };
            let rt = word & 0x1F;
            let mnemonic = if opcode_id == "TBZ" { "tbz" } else { "tbnz" };
            decoded.mnemonic = mnemonic.to_string();
            decoded.operands.clear();
            decoded.operands.push(Operand::Text {
                value: format!("{}{}", reg_size, rt),
            });
            decoded.operands.push(Operand::Text {
                value: format!("#{}", bit_pos),
            });
            decoded.operands.push(Operand::Text {
                value: format_branch_target(target),
            });
        }
        "ADR" => {
            let immlo = ((word >> 29) & 0x3) as i32;
            let immhi = ((word >> 5) & 0x7FFFF) as i32;
            let imm21 = sign_extend((immhi << 2) | immlo, 21);
            let target = (address as i64).wrapping_add(imm21 as i64) as u64;
            if let Some(Operand::Register { register }) = decoded.operands.first() {
                let rd = register.id;
                decoded.operands.clear();
                decoded.operands.push(Operand::Text {
                    value: format!("x{rd}"),
                });
            }
            decoded.operands.push(Operand::Text {
                value: format_branch_target(target),
            });
        }
        "ADRP" => {
            let immlo = ((word >> 29) & 0x3) as i64;
            let immhi = ((word >> 5) & 0x7FFFF) as i64;
            let imm21 = sign_extend64((immhi << 2) | immlo, 21);
            let target = (address as i64 & !0xFFF).wrapping_add(imm21 << 12);
            if let Some(Operand::Register { register }) = decoded.operands.first() {
                let rd = register.id;
                decoded.operands.clear();
                decoded.operands.push(Operand::Text {
                    value: format!("x{rd}"),
                });
            }
            decoded.operands.push(Operand::Text {
                value: format_branch_target(target as u64),
            });
        }
        "LDR_LIT_W" | "LDR_LIT_X" | "LDRSW_LIT" => {
            let imm19 = ((word >> 5) & 0x7FFFF) as i32;
            let offset = sign_extend(imm19, 19) << 2;
            let target = (address as i64).wrapping_add(offset as i64) as u64;
            let rt = word & 0x1F;
            let reg_size = match opcode_id {
                "LDR_LIT_W" => "w",
                "LDR_LIT_X" => "x",
                "LDRSW_LIT" => "x",
                _ => "x",
            };
            decoded.mnemonic = match opcode_id {
                "LDRSW_LIT" => "ldrsw",
                _ => "ldr",
            }
            .to_string();
            decoded.operands.clear();
            decoded.operands.push(Operand::Text {
                value: format!("{}{}", reg_size, rt),
            });
            decoded.operands.push(Operand::Text {
                value: format_branch_target(target),
            });
        }
        _ => {}
    }

    // Integer aliases.
    match opcode_id {
        "SUBS_IMM" | "ADDS_IMM" => {
            // CMP alias: when Rd is xzr/sp (register 31), omit it.
            let rd = word & 0x1F;
            if rd == 31 {
                let base = if opcode_id.starts_with("SUBS") {
                    "cmp"
                } else {
                    "cmn"
                };
                decoded.mnemonic = base.to_string();
                if decoded.operands.len() >= 3 {
                    decoded.operands.remove(0); // Remove Rd
                }
            }
        }
        "SUB_REG" | "SUB_IMM" => {
            // NEG alias: when Rn is sp/xzr (register 31).
            let rn = (word >> 5) & 0x1F;
            if rn == 31 && decoded.operands.len() >= 3 {
                decoded.mnemonic = "neg".to_string();
                decoded.operands.remove(1); // Remove Rn
            }
        }
        "MOVZ" => {
            // MOV alias: movz with hw == 0.
            let hw = (word >> 21) & 0x3;
            if hw == 0 {
                decoded.mnemonic = "mov".to_string();
            }
        }
        "ORR_REG" => {
            // MOV alias: orr with Rm=0 (shifted register).
            let rm = (word >> 16) & 0x1F;
            let imm6 = (word >> 10) & 0x3F;
            if rm == 31 && imm6 == 0 {
                decoded.mnemonic = "mov".to_string();
                if decoded.operands.len() >= 3 {
                    decoded.operands.remove(2); // Remove Rm
                }
            }
        }
        "RET" => {
            // Omit x30 as the default return address register.
            let rn = (word >> 5) & 0x1F;
            if rn == 30 {
                decoded.operands.clear();
            }
        }
        "SVC" => {
            // SVC #imm — immediate is already formatted with # prefix.
        }
        _ => {}
    }

    // System/barrier aliases.
    match opcode_id {
        "DSB" | "DMB" => {
            // CRm field at bits 11:8 holds the barrier option.
            let crm = (word >> 8) & 0xF;
            let barrier_name = barrier_imm_name(crm);
            decoded.operands.clear();
            decoded.operands.push(Operand::Text {
                value: barrier_name,
            });
        }
        _ => {}
    }
}

/// Sign-extend an n-bit signed integer.
fn sign_extend(value: i32, bits: u32) -> i32 {
    let shift = 32 - bits;
    (value << shift) >> shift
}

/// Sign-extend an n-bit signed integer (64-bit).
fn sign_extend64(value: i64, bits: u32) -> i64 {
    let shift = 64 - bits;
    (value << shift) >> shift
}

/// AArch64 condition code names.
fn condition_name(cond: u32) -> &'static str {
    match cond {
        0x0 => "eq",
        0x1 => "ne",
        0x2 => "cs",
        0x3 => "cc",
        0x4 => "mi",
        0x5 => "pl",
        0x6 => "vs",
        0x7 => "vc",
        0x8 => "hi",
        0x9 => "ls",
        0xa => "ge",
        0xb => "lt",
        0xc => "gt",
        0xd => "le",
        0xe => "al",
        0xf => "nv",
        _ => "al",
    }
}

/// Barrier immediate value to name mapping.
fn barrier_imm_name(imm: u32) -> String {
    match imm {
        0xf => "sy".to_string(),
        0xe => "st".to_string(),
        0xb => "ish".to_string(),
        0xa => "ishst".to_string(),
        0x9 => "ishld".to_string(),
        0x7 => "nsh".to_string(),
        0x6 => "nshst".to_string(),
        0x5 => "nshld".to_string(),
        0x3 => "osh".to_string(),
        0x2 => "oshst".to_string(),
        0x1 => "oshld".to_string(),
        0 => "#0".to_string(),
        _ => format!("#{}", imm),
    }
}

/// Format a branch target address in Capstone-compatible style.
fn format_branch_target(target: u64) -> String {
    if target == 0 {
        "0".to_string()
    } else {
        format!("0x{target:x}")
    }
}

/// Decode element size from the bottom 5 bits of an imm5 field.
fn simd_element_size_from_imm5(imm5: u8) -> u8 {
    if imm5 & 1 != 0 {
        0
    } else if imm5 & 2 != 0 {
        1
    } else if imm5 & 4 != 0 {
        2
    } else if imm5 & 8 != 0 {
        3
    } else {
        0
    }
}

/// Return the element type character for a given size (b, h, s, d).
fn element_type_suffix(size: u8) -> &'static str {
    match size {
        0 => "b",
        1 => "h",
        2 => "s",
        3 => "d",
        _ => "",
    }
}

/// True if the opcode is a floating-point vector (SIMD) operation.
fn is_fp_vector_opcode(opcode_id: &str) -> bool {
    matches!(
        opcode_id,
        "VEC_FADD"
            | "VEC_FSUB"
            | "VEC_FMUL"
            | "VEC_FDIV"
            | "VEC_FMAX"
            | "VEC_FMIN"
            | "VEC_FMAXNM"
            | "VEC_FMINNM"
            | "VEC_FMLA"
            | "VEC_FMLS"
            | "VEC_FADDP"
            | "VEC_FMAXP"
            | "VEC_FMINP"
            | "VEC_FMAXNMP"
            | "VEC_FMINNMP"
            | "VEC_FCMEQ_REG"
            | "VEC_FCMGE_REG"
            | "VEC_FCMGT_REG"
            | "VEC_FCMLE_ZERO"
            | "VEC_FCMLT_ZERO"
            | "VEC_FRECPS"
            | "VEC_FRSQRTS"
            | "VEC_FMULX"
            | "VEC_FABD"
            | "VEC_FACGE"
            | "VEC_FACGT"
            | "VEC_FCVTN"
            | "VEC_FSQRT"
            | "VEC_FRSQRTE"
            | "VEC_FMAXV_H"
            | "VEC_FMAXV_S"
            | "VEC_FMINV_H"
            | "VEC_FMINV_S"
            | "VEC_FMAXNMV"
            | "VEC_FMINNMV"
            | "VEC_FABS"
            | "VEC_FNEG"
            | "VEC_FRECPE"
            | "VEC_FCMEQ_ZERO"
            | "VEC_FCMGT_ZERO"
            | "VEC_FCMGE_ZERO"
    )
}

/// True if the opcode is a SHA three-register cryptographic instruction.
fn is_sha_three_reg_opcode(opcode_id: &str) -> bool {
    matches!(
        opcode_id,
        "VEC_SHA1C"
            | "VEC_SHA1P"
            | "VEC_SHA1M"
            | "VEC_SHA1SU0"
            | "VEC_SHA256H"
            | "VEC_SHA256H2"
            | "VEC_SHA256SU1"
    )
}

/// True if the opcode is a table lookup instruction (TBL or TBX).
fn is_table_lookup_opcode(opcode_id: &str) -> bool {
    matches!(
        opcode_id,
        "VEC_TBL1"
            | "VEC_TBL2"
            | "VEC_TBL3"
            | "VEC_TBL4"
            | "VEC_TBX1"
            | "VEC_TBX2"
            | "VEC_TBX3"
            | "VEC_TBX4"
    )
}

/// True if the opcode is a copy/extract instruction (DUP, INS, EXT, SMOV, UMOV).
fn is_copy_extract_opcode(opcode_id: &str) -> bool {
    matches!(
        opcode_id,
        "VEC_DUP_ELEMENT"
            | "VEC_DUP_GENERAL"
            | "VEC_INS_ELEMENT"
            | "VEC_INS_GENERAL"
            | "VEC_SMOV"
            | "VEC_UMOV"
            | "VEC_EXT"
    )
}

/// True if the opcode uses an indexed vector element operand.
fn is_indexed_element_opcode(opcode_id: &str) -> bool {
    matches!(
        opcode_id,
        "VEC_MLA_INDEXED"
            | "VEC_MLS_INDEXED"
            | "VEC_MUL_INDEXED"
            | "VEC_FMLA_INDEXED"
            | "VEC_FMLS_INDEXED"
            | "VEC_FMUL_INDEXED"
            | "VEC_FMULX_INDEXED"
            | "VEC_SMLAL_INDEXED"
            | "VEC_UMLAL_INDEXED"
            | "VEC_SQDMLAL_INDEXED"
            | "VEC_SMLSL_INDEXED"
            | "VEC_UMLSL_INDEXED"
            | "VEC_SQDMLSL_INDEXED"
            | "VEC_SMULL_INDEXED"
            | "VEC_UMULL_INDEXED"
            | "VEC_SQDMULL_INDEXED"
            | "VEC_SQDMULH_INDEXED"
            | "VEC_SQRDMULH_INDEXED"
            | "VEC_FMLAL2_INDEXED"
    )
}

/// True if the opcode is a floating-point indexed element instruction.
fn is_fp_indexed_opcode(opcode_id: &str) -> bool {
    matches!(
        opcode_id,
        "VEC_FMLA_INDEXED" | "VEC_FMLS_INDEXED" | "VEC_FMUL_INDEXED" | "VEC_FMULX_INDEXED"
    )
}

/// True if the opcode is a long (widening) indexed element instruction.
fn is_long_indexed_opcode(opcode_id: &str) -> bool {
    matches!(
        opcode_id,
        "VEC_SMLAL_INDEXED"
            | "VEC_UMLAL_INDEXED"
            | "VEC_SQDMLAL_INDEXED"
            | "VEC_SMLSL_INDEXED"
            | "VEC_UMLSL_INDEXED"
            | "VEC_SQDMLSL_INDEXED"
            | "VEC_SMULL_INDEXED"
            | "VEC_UMULL_INDEXED"
            | "VEC_SQDMULL_INDEXED"
            | "VEC_FMLAL2_INDEXED"
    )
}

/// True if the opcode is a vector shift-by-immediate instruction.
fn is_shift_imm_opcode(opcode_id: &str) -> bool {
    matches!(
        opcode_id,
        "VEC_SHIFT_IMM_A" | "VEC_SHIFT_IMM_A_U1" | "VEC_SHIFT_IMM_B" | "VEC_SHIFT_IMM_B_U1"
    )
}

/// True if the opcode is a vector modified-immediate instruction (MOVI, MVNI, ORR, BIC).
fn is_modified_imm_opcode(opcode_id: &str) -> bool {
    matches!(opcode_id, "VEC_MODIFIED_IMM")
}

/// True if the opcode is a scalar floating-point instruction.
fn is_scalar_fp_opcode(opcode_id: &str) -> bool {
    matches!(
        opcode_id,
        "FADD"
            | "FSUB"
            | "FMUL"
            | "FDIV"
            | "FMAX"
            | "FMIN"
            | "FMAXNM"
            | "FMINNM"
            | "FNMUL"
            | "FCMP"
            | "FCMPE"
            | "FMOV"
            | "FABS"
            | "FNEG"
            | "FSQRT"
            | "FRINTN"
            | "FRINTP"
            | "FRINTM"
            | "FRINTZ"
            | "FRINTA"
            | "FRINTX"
            | "FRINTI"
            | "FCSEL"
            | "FMADD"
            | "FMSUB"
            | "FCVT_FP"
    )
}

/// True if the opcode is a load/store instruction.
fn is_loadstore_opcode(opcode_id: &str) -> bool {
    opcode_id.starts_with("LDR")
        || opcode_id.starts_with("STR")
        || opcode_id.starts_with("LDUR")
        || opcode_id.starts_with("STUR")
        || opcode_id.starts_with("LDP")
        || opcode_id.starts_with("STP")
        || opcode_id.starts_with("STXR")
        || opcode_id.starts_with("LDXR")
        || opcode_id.starts_with("STXP")
        || opcode_id.starts_with("LDXP")
        || opcode_id == "SIMD_LS_LOAD"
        || opcode_id == "SIMD_LS_STORE"
}

/// Apply load/store aliases: combine base+offset into memory operand text.
fn apply_loadstore_aliases(
    decoded: &mut robustone_core::ir::DecodedInstruction,
    word: u32,
    opcode_id: &str,
) {
    use robustone_core::ir::Operand;

    let ops = &mut decoded.operands;
    if ops.len() < 2 {
        return;
    }

    // Determine register size prefix from opcode for data registers (Rt).
    let is_32bit = opcode_id.ends_with("_W")
        || opcode_id.ends_with("_B")
        || opcode_id.ends_with("_H")
        || opcode_id == "LDRSB_W"
        || opcode_id == "LDRSH_W";
    let data_prefix = if is_32bit { "w" } else { "x" };

    // FP/SIMD load/store: determine register prefix (s/d/q) from opcode.
    let fp_prefix = if opcode_id.ends_with("_S") {
        Some("s")
    } else if opcode_id.ends_with("_D") {
        Some("d")
    } else if opcode_id.ends_with("_Q") {
        Some("q")
    } else {
        None
    };

    // Helper: format a GPR with explicit prefix.
    let fmt_reg = |id: u32, prefix: &str| -> String {
        match id {
            0..=30 => format!("{}{}", prefix, id),
            31 if prefix == "w" => "wsp".to_string(),
            31 => "sp".to_string(),
            _ => format!("r{}", id),
        }
    };

    // Helper to extract register name. Base registers are always xN.
    let reg_name = |op: &Operand| -> String {
        match op {
            Operand::Register { register } => {
                if register.architecture == ArchitectureId::Arm && (64..96).contains(&register.id) {
                    format!("v{}", register.id - 64)
                } else if register.architecture == ArchitectureId::Arm {
                    fmt_reg(register.id, "x")
                } else {
                    format!("r{}", register.id)
                }
            }
            _ => String::new(),
        }
    };

    // Helper to format a data register with the correct size.
    let data_reg_name = |op: &Operand| -> String {
        match op {
            Operand::Register { register } => {
                if register.architecture == ArchitectureId::Arm && (64..96).contains(&register.id) {
                    if let Some(prefix) = fp_prefix {
                        format!("{}{}", prefix, register.id - 64)
                    } else {
                        format!("v{}", register.id - 64)
                    }
                } else if register.architecture == ArchitectureId::Arm {
                    fmt_reg(register.id, data_prefix)
                } else {
                    format!("r{}", register.id)
                }
            }
            _ => String::new(),
        }
    };

    // Helper to extract immediate value.
    let imm_val = |op: &Operand| -> i64 {
        match op {
            Operand::Immediate { value, .. } => *value,
            _ => 0,
        }
    };

    // Determine operand structure based on opcode.
    let is_pair = opcode_id.starts_with("LDP") || opcode_id.starts_with("STP");
    let is_literal = opcode_id.starts_with("LDR_LIT") || opcode_id == "LDRSW_LIT";
    let is_post = opcode_id.contains("POST");
    let is_pre = opcode_id.contains("PRE");
    let is_unscaled = opcode_id.starts_with("LDUR") || opcode_id.starts_with("STUR");
    let is_reg = opcode_id.contains("REG");
    let is_excl = opcode_id.starts_with("STXR") || opcode_id.starts_with("LDXR");
    let is_excl_pair = opcode_id.starts_with("STXP") || opcode_id.starts_with("LDXP");

    // Advanced SIMD load/store: register list + memory operand.
    if opcode_id == "SIMD_LS_LOAD" || opcode_id == "SIMD_LS_STORE" {
        let q = ((word >> 30) & 0x1) as u8;
        let size = ((word >> 10) & 0x3) as u8;
        let opcode = ((word >> 12) & 0xF) as u8;
        let rt = (word & 0x1F) as u8;
        let rn = ((word >> 5) & 0x1F) as u8;
        let l = ((word >> 22) & 0x1) as u8;

        let arr = vec_arrangement_suffix(size, q);
        let (mnemonic, num_regs) = match opcode {
            0x0 => (if l == 1 { "ld4" } else { "st4" }, 4),
            0x2 => (if l == 1 { "ld1" } else { "st1" }, 4),
            0x4 => (if l == 1 { "ld3" } else { "st3" }, 3),
            0x6 => (if l == 1 { "ld1" } else { "st1" }, 3),
            0x7 => (if l == 1 { "ld1" } else { "st1" }, 1),
            0x8 => (if l == 1 { "ld2" } else { "st2" }, 2),
            0xA => (if l == 1 { "ld1" } else { "st1" }, 2),
            _ => (if l == 1 { "ld1" } else { "st1" }, 1),
        };
        decoded.mnemonic = mnemonic.to_string();

        let mut list = String::new();
        list.push('{');
        for i in 0..num_regs {
            if i > 0 {
                list.push_str(", ");
            }
            list.push_str(&format!("v{}{}", rt + i as u8, arr));
        }
        list.push('}');

        let base = match rn {
            0..=30 => format!("x{}", rn),
            31 => "sp".to_string(),
            _ => format!("r{}", rn),
        };

        ops.clear();
        ops.push(Operand::Text { value: list });
        ops.push(Operand::Text {
            value: format!("[{}]", base),
        });
        return;
    }

    if is_literal {
        // Literal: ldr x0, <label> — operands are [Rt, imm19]
        // Compute PC-relative target.
        let imm19 = ((word >> 5) & 0x7FFFF) as i32;
        let offset = sign_extend(imm19, 19) << 2;
        let target = (decoded.address as i64).wrapping_add(offset as i64) as u64;
        if !ops.is_empty() {
            ops[0] = Operand::Text {
                value: data_reg_name(&ops[0]),
            };
        }
        if ops.len() >= 2 {
            ops[1] = Operand::Text {
                value: format_branch_target(target),
            };
        }
        return;
    }

    if is_excl_pair {
        // stxp ws, wt1, wt2, [xn]
        // Status register (Rs) is always 32-bit (wN).
        if !ops.is_empty()
            && let Operand::Register { register } = &ops[0]
        {
            ops[0] = Operand::Text {
                value: fmt_reg(register.id, "w"),
            };
        }
        if ops.len() > 1 {
            ops[1] = Operand::Text {
                value: data_reg_name(&ops[1]),
            };
        }
        if ops.len() > 2 {
            ops[2] = Operand::Text {
                value: data_reg_name(&ops[2]),
            };
        }
        if ops.len() >= 4 {
            let base = reg_name(&ops[3]);
            ops[3] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    if is_excl {
        // stxr ws, wt, [xn]
        // Status register (Rs) is always 32-bit (wN).
        if !ops.is_empty()
            && let Operand::Register { register } = &ops[0]
        {
            ops[0] = Operand::Text {
                value: fmt_reg(register.id, "w"),
            };
        }
        if ops.len() > 1 {
            ops[1] = Operand::Text {
                value: data_reg_name(&ops[1]),
            };
        }
        if ops.len() >= 3 {
            let base = reg_name(&ops[2]);
            ops[2] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    // Format data registers with correct size before memory operand handling.
    if is_pair {
        if !ops.is_empty() {
            ops[0] = Operand::Text {
                value: data_reg_name(&ops[0]),
            };
        }
        if ops.len() > 1 {
            ops[1] = Operand::Text {
                value: data_reg_name(&ops[1]),
            };
        }
    } else {
        if !ops.is_empty() {
            ops[0] = Operand::Text {
                value: data_reg_name(&ops[0]),
            };
        }
    }

    // For pair, normal, post, pre, unscaled, reg: memory operand is the last one or last two.
    // The format has [Rt, Rn, offset/Rm] or [Rt, Rt2, Rn, offset].
    let mem_idx = if is_pair {
        2 // Rn is at index 2 for LDP format
    } else {
        1 // Rn is at index 1 for single-register formats
    };

    if ops.len() <= mem_idx {
        return;
    }

    let base = reg_name(&ops[mem_idx]);

    if is_reg {
        // Register offset: [xn, xm]
        if ops.len() > mem_idx + 1 {
            let rm = reg_name(&ops[mem_idx + 1]);
            if !rm.is_empty() {
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}, {}]", base, rm),
                };
                ops.remove(mem_idx + 1);
            }
        }
        return;
    }

    if is_post {
        // Post-indexed: [xn], #offset
        if ops.len() > mem_idx + 1 {
            let offset = imm_val(&ops[mem_idx + 1]);
            let off_str = if offset >= 0 {
                format!("{}", offset)
            } else {
                format!("-{}", -offset)
            };
            ops[mem_idx] = Operand::Text {
                value: format!("[{}], #{}", base, off_str),
            };
            ops.remove(mem_idx + 1);
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    if is_pre {
        // Pre-indexed: [xn, #offset]!
        if ops.len() > mem_idx + 1 {
            let offset = imm_val(&ops[mem_idx + 1]);
            let off_str = if offset >= 0 {
                format!("{}", offset)
            } else {
                format!("-{}", -offset)
            };
            ops[mem_idx] = Operand::Text {
                value: format!("[{}, #{}]!", base, off_str),
            };
            ops.remove(mem_idx + 1);
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]!", base),
            };
        }
        return;
    }

    if is_unscaled {
        // Unscaled: [xn, #offset] or [xn] if offset=0
        if ops.len() > mem_idx + 1 {
            let offset = imm_val(&ops[mem_idx + 1]);
            if offset == 0 {
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}]", base),
                };
            } else {
                let off_str = if offset >= 0 {
                    format!("{}", offset)
                } else {
                    format!("-{}", -offset)
                };
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}, #{}]", base, off_str),
                };
            }
            ops.remove(mem_idx + 1);
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    if is_pair {
        // Pair: [xn, #offset] or [xn] if offset=0
        if ops.len() > mem_idx + 1 {
            let offset = imm_val(&ops[mem_idx + 1]);
            // Pair offset is scaled: imm7 * scale
            let scale = if opcode_id.contains("_X") || opcode_id.contains("_D") {
                8
            } else {
                4
            };
            let scaled = offset * scale;
            if scaled == 0 {
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}]", base),
                };
            } else {
                ops[mem_idx] = Operand::Text {
                    value: format!("[{}, #{}]", base, scaled),
                };
            }
            ops.remove(mem_idx + 1);
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]", base),
            };
        }
        return;
    }

    // Unsigned immediate: [xn, #offset] or [xn] if offset=0
    // Offset is scaled: imm12 * scale
    let scale = if opcode_id.ends_with("_X")
        || opcode_id.ends_with("H")
        || opcode_id == "LDRSH_X"
        || opcode_id == "LDRSB_X"
    {
        if opcode_id.ends_with("H") && !opcode_id.starts_with("LDRS") {
            2
        } else {
            8
        }
    } else if opcode_id.ends_with("W")
        || opcode_id.ends_with("B")
        || opcode_id == "LDRSB_W"
        || opcode_id == "LDRSH_W"
    {
        if opcode_id.ends_with("B") && !opcode_id.starts_with("LDRS") {
            1
        } else {
            4
        }
    } else {
        1
    };

    if ops.len() > mem_idx + 1 {
        let offset = imm_val(&ops[mem_idx + 1]);
        let scaled = offset * scale;
        if scaled == 0 {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}]", base),
            };
        } else {
            ops[mem_idx] = Operand::Text {
                value: format!("[{}, #{}]", base, scaled),
            };
        }
        ops.remove(mem_idx + 1);
    } else {
        ops[mem_idx] = Operand::Text {
            value: format!("[{}]", base),
        };
    }
}

/// Return the vector arrangement suffix for a modified-immediate instruction.
fn modified_imm_arrangement(cmode: u8, q: u8, op: u8) -> &'static str {
    match cmode {
        0..=7 => match q {
            0 => ".2s",
            1 => ".4s",
            _ => "",
        },
        8..=11 => match q {
            0 => ".4h",
            1 => ".8h",
            _ => "",
        },
        12..=13 => match q {
            0 => ".2s",
            1 => ".4s",
            _ => "",
        },
        14 => match (op, q) {
            (0, 0) => ".8b",
            (0, 1) => ".16b",
            (1, 0) => "", // scalar d
            (1, 1) => ".2d",
            _ => "",
        },
        15 => modified_imm_fp_arrangement(q, op),
        _ => "",
    }
}

/// Return the FP arrangement suffix for a modified-immediate FMOV.
fn modified_imm_fp_arrangement(q: u8, op: u8) -> &'static str {
    match (op, q) {
        (0, 0) => ".2s",
        (0, 1) => ".4s",
        (1, 1) => ".2d",
        _ => "",
    }
}

/// Compute the left-shift amount for a modified-immediate cmode value.
fn modified_imm_shift(cmode: u8) -> u8 {
    match cmode {
        0 | 1 | 8 | 9 => 0,
        2 | 3 | 10 | 11 => 8,
        4 | 5 => 16,
        6 | 7 => 24,
        12 => 8,
        13 => 16,
        _ => 0,
    }
}

/// Expand an 8-bit FP immediate into a `f64` value per ARM ARM.
fn fp_expand_imm(imm8: u8, op: u8, q: u8) -> f64 {
    let a = ((imm8 >> 7) & 1) as u32;
    let b = ((imm8 >> 6) & 1) as u32;
    let c = ((imm8 >> 5) & 1) as u32;
    let d = ((imm8 >> 4) & 1) as u32;
    let e = ((imm8 >> 3) & 1) as u32;
    let f = ((imm8 >> 2) & 1) as u32;
    let g = ((imm8 >> 1) & 1) as u32;
    let h = (imm8 & 1) as u32;

    let sign = a;

    if op == 1 || q == 1 {
        // Double precision
        let exp = ((1 - b) << 10)
            | (b << 9)
            | (c << 8)
            | (d << 7)
            | (b << 6)
            | (b << 5)
            | (b << 4)
            | (b << 3)
            | (b << 2)
            | (b << 1)
            | b;
        let frac =
            ((e as u64) << 51) | ((f as u64) << 50) | ((g as u64) << 49) | ((h as u64) << 48);
        let bits = ((sign as u64) << 63) | ((exp as u64) << 52) | frac;
        f64::from_bits(bits)
    } else {
        // Single precision
        let exp =
            ((1 - b) << 7) | (b << 6) | (c << 5) | (d << 4) | (b << 3) | (b << 2) | (b << 1) | b;
        let frac = (e << 22) | (f << 21) | (g << 20) | (h << 19);
        let bits = (sign << 31) | (exp << 23) | frac;
        f32::from_bits(bits) as f64
    }
}

/// Return the vector arrangement suffix (e.g. `.8b`, `.4s`) for integer SIMD.
fn vec_arrangement_suffix(size: u8, q: u8) -> &'static str {
    match (size, q) {
        (0, 0) => ".8b",
        (0, 1) => ".16b",
        (1, 0) => ".4h",
        (1, 1) => ".8h",
        (2, 0) => ".2s",
        (2, 1) => ".4s",
        (3, 1) => ".2d",
        _ => "",
    }
}

/// Return the vector arrangement suffix for FP SIMD operations.
fn fp_vec_arrangement_suffix(size: u8, q: u8) -> &'static str {
    // FP vector uses bit 22 (the lower bit of size) as element size:
    // bit 22 = 0 → S (single), bit 22 = 1 → D (double)
    let elem_size = size & 0x1;
    match (elem_size, q) {
        (0, 0) => ".2s",
        (0, 1) => ".4s",
        (1, 1) => ".2d",
        _ => "",
    }
}

/// Return the vector arrangement suffix for FP indexed-element operations.
fn fp_indexed_arrangement_suffix(size: u8, q: u8) -> &'static str {
    // FP indexed element uses size directly:
    // size=00 → FP16 (H), size=10 → S, size=11 → D
    match (size, q) {
        (0, 0) => ".4h",
        (0, 1) => ".8h",
        (2, 0) => ".2s",
        (2, 1) => ".4s",
        (3, 1) => ".2d",
        _ => "",
    }
}

/// Derive the element size (8, 16, 32, 64) from the `immh` field of a shift-immediate instruction.
fn shift_imm_esize(immh: u8) -> u8 {
    match immh {
        0b0001 => 8,
        0b0010 | 0b0011 => 16,
        0b0100..=0b0111 => 32,
        0b1000..=0b1111 => 64,
        _ => 0,
    }
}

/// Return the vector arrangement suffix for a shift-immediate instruction.
fn shift_imm_arrangement(esize: u8, q: u8) -> &'static str {
    match (esize, q) {
        (8, 0) => ".8b",
        (8, 1) => ".16b",
        (16, 0) => ".4h",
        (16, 1) => ".8h",
        (32, 0) => ".2s",
        (32, 1) => ".4s",
        (64, 1) => ".2d",
        _ => "",
    }
}

// ---------------------------------------------------------------------------
// Formats
// ---------------------------------------------------------------------------

robustone_isa_macros::define_formats! {
    arch = Arm;
    extern_fields;
    fields { Rd; Rn; Rm; Ra; Rt; Rt2; Rs; Imm9; Imm12; Imm16; Imm19; Imm26; Immhi; Immlo; Imm7; Cond; Shift; Imm6; Hw; N; Immr; Imms; Ftype; Opcode; Size; Q; U; L; M; H; };

    format R_TYPE {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
    };
    format R_4REG {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
        ra: bits(10, 5) as Ra,
    };
    format R_COND {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
        cond: bits(12, 4) as Cond,
    };
    format R_DP_REG {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        imm6: bits(10, 6) as Imm6,
        rm: bits(16, 5) as Rm,
        shift: bits(22, 2) as Shift,
    };
    format R_LOGICAL {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        imm6: bits(10, 6) as Imm6,
        rm: bits(16, 5) as Rm,
        n: bits(21, 1) as N,
        shift: bits(22, 2) as Shift,
    };
    format R_CONDSEL {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        cond: bits(12, 4) as Cond,
        rm: bits(16, 5) as Rm,
    };
    format I_ADD {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        imm12: bits(10, 12) as Imm12,
        shift: bits(22, 1) as Shift,
    };
    format I_LOGICAL {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        imms: bits(10, 6) as Imms,
        immr: bits(16, 6) as Immr,
        n: bits(22, 1) as N,
    };
    format I_BITFIELD {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        imms: bits(10, 6) as Imms,
        immr: bits(16, 6) as Immr,
    };
    format I_MOVZ {
        rd: bits(0, 5) as Rd,
        imm16: bits(5, 16) as Imm16,
        hw: bits(21, 2) as Hw,
    };
    format B_UNCOND {
        imm26: bits(0, 26) as Imm26,
    };
    format FMT_B_COND {
        imm19: bits(5, 19) as Imm19,
        cond: bits(0, 4) as Cond,
    };
    format FMT_CBZ {
        rt: bits(0, 5) as Rt,
        imm19: bits(5, 19) as Imm19,
    };
    format FMT_TBZ {
        rt: bits(0, 5) as Rt,
        imm14: bits(5, 14) as Imm19,
        b5: bits(19, 1) as Q,
        b40: bits(24, 5) as Imm6,
    };
    format FMT_ADR {
        rd: bits(0, 5) as Rd,
        immhi: bits(5, 19) as Immhi,
        immlo: bits(29, 2) as Immlo,
    };
    format EXCEPT {
        imm16: bits(5, 16) as Imm16,
    };
    format BARRIER {
        crm: bits(8, 4) as Imm6,
    };
    format LDR_IMM {
        rt: bits(0, 5) as Rt,
        rn: bits(5, 5) as Rn,
        imm12: bits(10, 12) as Imm12,
    };
    format LDR_REG {
        rt: bits(0, 5) as Rt,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
        option: bits(13, 3) as Opcode,
        s: bits(12, 1) as Shift,
    };
    format LDP {
        rt: bits(0, 5) as Rt,
        rt2: bits(10, 5) as Rt2,
        rn: bits(5, 5) as Rn,
        imm7: bits(15, 7) as Imm7,
    };
    format LDR_LIT {
        rt: bits(0, 5) as Rt,
        imm19: bits(5, 19) as Imm19,
    };
    format LDR_POST {
        rt: bits(0, 5) as Rt,
        rn: bits(5, 5) as Rn,
        imm9: bits(12, 9) as Imm9,
    };
    format LDR_PRE {
        rt: bits(0, 5) as Rt,
        rn: bits(5, 5) as Rn,
        imm9: bits(12, 9) as Imm9,
    };
    format LDR_UNSCALED {
        rt: bits(0, 5) as Rt,
        rn: bits(5, 5) as Rn,
        imm9: bits(12, 9) as Imm9,
    };
    format LDR_EXCL {
        rt: bits(0, 5) as Rt,
        rn: bits(5, 5) as Rn,
        rs: bits(16, 5) as Rs,
    };
    format LDR_EXCL_PAIR {
        rt: bits(0, 5) as Rt,
        rn: bits(5, 5) as Rn,
        rt2: bits(10, 5) as Rt2,
        rs: bits(16, 5) as Rs,
    };
    format FP_1SOURCE {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        ftype: bits(22, 2) as Ftype,
    };
    format FP_2SOURCE {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
        ftype: bits(22, 2) as Ftype,
    };
    format FP_CONDSEL {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
        cond: bits(12, 4) as Cond,
        ftype: bits(22, 2) as Ftype,
    };
    format FP_3SOURCE {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
        ra: bits(10, 5) as Ra,
        ftype: bits(22, 2) as Ftype,
    };
    format VEC_THREE_SAME {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
        size: bits(22, 2) as Size,
        q: bits(30, 1) as Q,
    };
    format VEC_TWO_REG {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        size: bits(22, 2) as Size,
        q: bits(30, 1) as Q,
    };
    format VEC_CRYPTO2 {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
    };
    format VEC_CRYPTO3 {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
    };
    format VEC_TABLE {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
    };
    format VEC_COPY {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
    };
    format VEC_COPY_INS {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
    };
    format VEC_EXT_FMT {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        rm: bits(16, 5) as Rm,
    };
    format VEC_SHIFT_IMM {
        rd: bits(0, 5) as Rd,
        rn: bits(5, 5) as Rn,
        imm7: bits(16, 7) as Imm7,
        q: bits(30, 1) as Q,
    };
    format FMT_VEC_MODIFIED_IMM {
        rd: bits(0, 5) as Rd,
        q: bits(30, 1) as Q,
    };
    format SIMD_LS {
        rt: bits(0, 5) as Rt,
        rn: bits(5, 5) as Rn,
        size: bits(10, 2) as Size,
        opcode: bits(12, 4) as Opcode,
        q: bits(30, 1) as Q,
    };
}

